22	@Name("cat")
23	@Summary("Concatenate and print files")
24	public class CatCommand extends AnnotatedCommand {
25	    private static final Logger logger = LoggerFactory.getLogger(CatCommand.class);
26	    private List<String> files;
27	    private String encoding;
28	    private Integer sizeLimit = 128 * 1024;
29	    private int maxSizeLimit = 8 * 1024 * 1024;
30	
31	    @Argument(argName = "files", index = 0)
32	    @Description("files")
33	    public void setFiles(List<String> files) {
34	        this.files = files;
35	    }
36	
37	    @Option(longName = "encoding")
38	    @Description("File encoding")
39	    public void setEncoding(String encoding) {
40	        this.encoding = encoding;
41	    }
42	
43	    @Option(shortName = "M", longName = "sizeLimit")
44	    @Description("Upper size limit in bytes for the result (128 * 1024 by default, the maximum value is 8 * 1024 * 1024)")
45	    public void setSizeLimit(Integer sizeLimit) {
46	        this.sizeLimit = sizeLimit;
47	    }
48	
49	    @Override
50	    public void process(CommandProcess process) {
51	        if (!verifyOptions(process)) {
52	            return;
53	        }
54	
55	        for (String file : files) {
56	            File f = new File(file);
57	            if (!f.exists()) {
58	                process.end(-1, "cat " + file + ": No such file or directory");
59	                return;
60	            }
61	            if (f.isDirectory()) {
62	                process.end(-1, "cat " + file + ": Is a directory");
63	                return;
64	            }
65	        }
66	
67	        for (String file : files) {
68	            File f = new File(file);
69	            if (f.length() > sizeLimit) {
70	                process.end(-1, "cat " + file + ": Is too large, size: " + f.length());
71	                return;
72	            }
73	            try {
74	                String fileToString = FileUtils.readFileToString(f,
75	                        encoding == null ? Charset.defaultCharset() : Charset.forName(encoding));
76	                process.appendResult(new CatModel(file, fileToString));
77	            } catch (IOException e) {
78	                logger.error("cat read file error. name: " + file, e);
79	                process.end(1, "cat read file error: " + e.getMessage());
80	                return;
81	            }
82	        }
83	
84	        process.end();
85	    }
86	
87	    private boolean verifyOptions(CommandProcess process) {
88	        if (sizeLimit > maxSizeLimit) {
89	            process.end(-1, "sizeLimit cannot be large than: " + maxSizeLimit);
90	            return false;
91	        }
92	
93	        //目前不支持过滤，限制http请求执行的文件大小
94	        int maxSizeLimitOfNonTty = 128 * 1024;
95	        if (!process.session().isTty() && sizeLimit > maxSizeLimitOfNonTty) {
96	            process.end(-1, "When executing in non-tty session, sizeLimit cannot be large than: " + maxSizeLimitOfNonTty);
97	            return false;
98	        }
99	        return true;
100	    }
101	
102	    @Override
103	    public void complete(Completion completion) {
104	        if (!CompletionUtils.completeFilePath(completion)) {
105	            super.complete(completion);
106	        }
107	    }
108	
109	}
