30	/**
31	 * 
32	 * @author hengyunabc 2021-01-05
33	 *
34	 */
35	@Name("base64")
36	@Summary("Encode and decode using Base64 representation")
37	@Description(Constants.EXAMPLE +
38	        "  base64 /tmp/test.txt\n" +
39	        "  base64 --input /tmp/test.txt --output /tmp/result.txt\n" +
40	        "  base64 -d /tmp/result.txt\n"
41	        + Constants.WIKI + Constants.WIKI_HOME + "base64")
42	public class Base64Command extends AnnotatedCommand {
43	    private static final Logger logger = LoggerFactory.getLogger(Base64Command.class);
44	    private String file;
45	    private int sizeLimit = 128 * 1024;
46	    private static final int MAX_SIZE_LIMIT = 8 * 1024 * 1024;
47	
48	    private boolean decode;
49	
50	    private String input;
51	    private String output;
52	
53	    @Argument(argName = "file", index = 0, required = false)
54	    @Description("file")
55	    public void setFiles(String file) {
56	        this.file = file;
57	    }
58	
59	    @Option(shortName = "d", longName = "decode", flag = true)
60	    @Description("decodes input")
61	    public void setDecode(boolean decode) {
62	        this.decode = decode;
63	    }
64	
65	    @Option(shortName = "i", longName = "input")
66	    @Description("input file")
67	    public void setInput(String input) {
68	        this.input = input;
69	    }
70	
71	    @Option(shortName = "o", longName = "output")
72	    @Description("output file")
73	    public void setOutput(String output) {
74	        this.output = output;
75	    }
76	
77	    @Option(shortName = "M", longName = "sizeLimit")
78	    @Description("Upper size limit in bytes for the result (128 * 1024 by default, the maximum value is 8 * 1024 * 1024)")
79	    public void setSizeLimit(Integer sizeLimit) {
80	        this.sizeLimit = sizeLimit;
81	    }
82	
83	    @Override
84	    public void process(CommandProcess process) {
85	        if (!verifyOptions(process)) {
86	            return;
87	        }
88	
89	        // 确认输入
90	        if (file == null) {
91	            if (this.input != null) {
92	                file = input;
93	            } else {
94	                process.end(-1, ": No file, nor input");
95	                return;
96	            }
97	        }
98	
99	        File f = new File(file);
100	        if (!f.exists()) {
101	            process.end(-1, file + ": No such file or directory");
102	            return;
103	        }
104	        if (f.isDirectory()) {
105	            process.end(-1, file + ": Is a directory");
106	            return;
107	        }
108	
109	        if (f.length() > sizeLimit) {
110	            process.end(-1, file + ": Is too large, size: " + f.length());
111	            return;
112	        }
113	
114	        InputStream input = null;
115	        ByteBuf convertResult = null;
116	
117	        try {
118	            input = new FileInputStream(f);
119	            byte[] bytes = IOUtils.getBytes(input);
120	
121	            if (this.decode) {
122	                convertResult = Base64.decode(Unpooled.wrappedBuffer(bytes));
123	            } else {
124	                convertResult = Base64.encode(Unpooled.wrappedBuffer(bytes));
125	            }
126	
127	            if (this.output != null) {
128	                int readableBytes = convertResult.readableBytes();
129	                OutputStream out = new FileOutputStream(this.output);
130	                convertResult.readBytes(out, readableBytes);
131	                process.appendResult(new Base64Model(null));
132	            } else {
133	                String base64Str = convertResult.toString(CharsetUtil.UTF_8);
134	                process.appendResult(new Base64Model(base64Str));
135	            }
136	        } catch (IOException e) {
137	            logger.error("read file error. name: " + file, e);
138	            process.end(1, "read file error: " + e.getMessage());
139	            return;
140	        } finally {
141	            if (convertResult != null) {
142	                convertResult.release();
143	            }
144	            IOUtils.close(input);
145	        }
146	
147	        process.end();
148	    }
149	
150	    private boolean verifyOptions(CommandProcess process) {
151	        if(this.file == null && this.input == null) {
152	            process.end(-1);
153	            return false;
154	        }
155	
156	        if (sizeLimit > MAX_SIZE_LIMIT) {
157	            process.end(-1, "sizeLimit cannot be large than: " + MAX_SIZE_LIMIT);
158	            return false;
159	        }
160	
161	        // 目前不支持过滤，限制http请求执行的文件大小
162	        int maxSizeLimitOfNonTty = 128 * 1024;
163	        if (!process.session().isTty() && sizeLimit > maxSizeLimitOfNonTty) {
164	            process.end(-1,
165	                    "When executing in non-tty session, sizeLimit cannot be large than: " + maxSizeLimitOfNonTty);
166	            return false;
167	        }
168	        return true;
169	    }
170	
171	    @Override
172	    public void complete(Completion completion) {
173	        if (!CompletionUtils.completeFilePath(completion)) {
174	            super.complete(completion);
175	        }
176	    }
177	
178	}
