32	/**
33	 * 展示类信息
34	 *
35	 * @author vlinux
36	 */
37	@Name("sc")
38	@Summary("Search all the classes loaded by JVM")
39	@Description(Constants.EXAMPLE +
40	        "  sc -d org.apache.commons.lang.StringUtils\n" +
41	        "  sc -d org/apache/commons/lang/StringUtils\n" +
42	        "  sc -d *StringUtils\n" +
43	        "  sc -d -f org.apache.commons.lang.StringUtils\n" +
44	        "  sc -E org\\\\.apache\\\\.commons\\\\.lang\\\\.StringUtils\n" +
45	        Constants.WIKI + Constants.WIKI_HOME + "sc")
46	public class SearchClassCommand extends AnnotatedCommand {
47	    private String classPattern;
48	    private boolean isDetail = false;
49	    private boolean isField = false;
50	    private boolean isRegEx = false;
51	    private String hashCode = null;
52	    private String classLoaderClass;
53	    private String classLoaderToString;
54	    private Integer expand;
55	    private int numberOfLimit = 100;
56	
57	    @Argument(argName = "class-pattern", index = 0)
58	    @Description("Class name pattern, use either '.' or '/' as separator")
59	    public void setClassPattern(String classPattern) {
60	        this.classPattern = StringUtils.normalizeClassName(classPattern);
61	    }
62	
63	    @Option(shortName = "d", longName = "details", flag = true)
64	    @Description("Display the details of class")
65	    public void setDetail(boolean detail) {
66	        isDetail = detail;
67	    }
68	
69	    @Option(shortName = "f", longName = "field", flag = true)
70	    @Description("Display all the member variables")
71	    public void setField(boolean field) {
72	        isField = field;
73	    }
74	
75	    @Option(shortName = "E", longName = "regex", flag = true)
76	    @Description("Enable regular expression to match (wildcard matching by default)")
77	    public void setRegEx(boolean regEx) {
78	        isRegEx = regEx;
79	    }
80	
81	    @Option(shortName = "x", longName = "expand")
82	    @Description("Expand level of object (0 by default)")
83	    public void setExpand(Integer expand) {
84	        this.expand = expand;
85	    }
86	
87	    @Option(shortName = "c", longName = "classloader")
88	    @Description("The hash code of the special class's classLoader")
89	    public void setHashCode(String hashCode) {
90	        this.hashCode = hashCode;
91	    }
92	
93	    @Option(longName = "classLoaderClass")
94	    @Description("The class name of the special class's classLoader.")
95	    public void setClassLoaderClass(String classLoaderClass) {
96	        this.classLoaderClass = classLoaderClass;
97	    }
98	
99	    @Option(shortName = "n", longName = "limits")
100	    @Description("Maximum number of matching classes with details (100 by default)")
101	    public void setNumberOfLimit(int numberOfLimit) {
102	        this.numberOfLimit = numberOfLimit;
103	    }
104	
105	    @Option(shortName = "cs", longName = "classLoaderStr")
106	    @Description("The return value of the special class's ClassLoader#toString().")
107	    public void setClassLoaderToString(String classLoaderToString) {
108	        this.classLoaderToString = classLoaderToString;
109	    }
110	
111	    @Override
112	    public void process(final CommandProcess process) {
113	        // TODO: null check
114	        RowAffect affect = new RowAffect();
115	        Instrumentation inst = process.session().getInstrumentation();
116	
117	        if (hashCode == null && (classLoaderClass != null || classLoaderToString != null)) {
118	            List<ClassLoader> matchedClassLoaders = ClassLoaderUtils.getClassLoader(inst, classLoaderClass, classLoaderToString);
119	            String tips = "";
120	            if (classLoaderClass != null) {
121	                tips = "class name: " + classLoaderClass;
122	            }
123	            if (classLoaderToString != null) {
124	                tips = tips + (StringUtils.isEmpty(tips) ? "ClassLoader#toString(): " : ", ClassLoader#toString(): ") + classLoaderToString;
125	            }
126	            if (matchedClassLoaders.size() == 1) {
127	                hashCode = Integer.toHexString(matchedClassLoaders.get(0).hashCode());
128	            } else if (matchedClassLoaders.size() > 1) {
129	                Collection<ClassLoaderVO> classLoaderVOList = ClassUtils.createClassLoaderVOList(matchedClassLoaders);
130	                SearchClassModel searchclassModel = new SearchClassModel()
131	                        .setClassLoaderClass(classLoaderClass)
132	                        .setMatchedClassLoaders(classLoaderVOList);
133	                process.appendResult(searchclassModel);
134	                process.end(-1, "Found more than one classloader by " + tips + ", please specify classloader with '-c <classloader hash>'");
135	                return;
136	            } else {
137	                process.end(-1, "Can not find classloader by " + tips + ".");
138	                return;
139	            }
140	        }
141	
142	        List<Class<?>> matchedClasses = new ArrayList<Class<?>>(SearchUtils.searchClass(inst, classPattern, isRegEx, hashCode));
143	        Collections.sort(matchedClasses, new Comparator<Class<?>>() {
144	            @Override
145	            public int compare(Class<?> c1, Class<?> c2) {
146	                return StringUtils.classname(c1).compareTo(StringUtils.classname(c2));
147	            }
148	        });
149	
150	        if (isDetail) {
151	            if (numberOfLimit > 0 && matchedClasses.size() > numberOfLimit) {
152	                process.end(-1, "The number of matching classes is greater than : " + numberOfLimit+". \n" +
153	                        "Please specify a more accurate 'class-patten' or use the parameter '-n' to change the maximum number of matching classes.");
154	                return;
155	            }
156	            for (Class<?> clazz : matchedClasses) {
157	                ClassDetailVO classInfo = ClassUtils.createClassInfo(clazz, isField, expand);
158	                process.appendResult(new SearchClassModel(classInfo, isDetail, isField));
159	            }
160	        } else {
161	            int pageSize = 256;
162	            ResultUtils.processClassNames(matchedClasses, pageSize, new ResultUtils.PaginationHandler<List<String>>() {
163	                @Override
164	                public boolean handle(List<String> classNames, int segment) {
165	                    process.appendResult(new SearchClassModel(classNames, segment));
166	                    return true;
167	                }
168	            });
169	        }
170	
171	        affect.rCnt(matchedClasses.size());
172	        process.appendResult(new RowAffectModel(affect));
173	        process.end();
174	    }
175	
176	    @Override
177	    public void complete(Completion completion) {
178	        if (!CompletionUtils.completeClassName(completion)) {
179	            super.complete(completion);
180	        }
181	    }
182	}
