51	public class SearchMethodCommand extends AnnotatedCommand {
52	    private static final Logger logger = LoggerFactory.getLogger(SearchMethodCommand.class);
53	
54	    private String classPattern;
55	    private String methodPattern;
56	    private String hashCode = null;
57	    private String classLoaderClass;
