101	        this.numberOfLimit = numberOfLimit;
102	    }
103	
104	    @Override
105	    public void process(CommandProcess process) {
106	        RowAffect affect = new RowAffect();
107	
108	        Instrumentation inst = process.session().getInstrumentation();
109	        Matcher<String> methodNameMatcher = methodNameMatcher();
110	        
111	        if (hashCode == null && classLoaderClass != null) {
112	            List<ClassLoader> matchedClassLoaders = ClassLoaderUtils.getClassLoaderByClassName(inst, classLoaderClass);
113	            if (matchedClassLoaders.size() == 1) {
114	                hashCode = Integer.toHexString(matchedClassLoaders.get(0).hashCode());
115	            } else if (matchedClassLoaders.size() > 1) {
116	                Collection<ClassLoaderVO> classLoaderVOList = ClassUtils.createClassLoaderVOList(matchedClassLoaders);
117	                SearchMethodModel searchmethodModel = new SearchMethodModel()
118	                        .setClassLoaderClass(classLoaderClass)
