    if (clazz.isArray()) {
        StringBuilder sb = new StringBuilder(clazz.getName());
        sb.delete(0, 2);
        if (sb.length() > 0 && sb.charAt(sb.length() - 1) == ';') {
            sb.deleteCharAt(sb.length() - 1);
        }
        sb.append("[]");
        return sb.toString();
    } else {
        return clazz.getName();
    }

